def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            minr = min(y for y,x in cells); maxr = max(y for y,x in cells)
            minc = min(x for y,x in cells); maxc = max(x for y,x in cells)
            shape = {(y-minr, x-minc) for y,x in cells}
            bh, bw = maxr-minr+1, maxc-minc+1
            # A completely enclosed background region identifies frame-like objects.
            outside = set()
            q = []
            for yy in range(bh):
                for xx in range(bw):
                    if (yy,xx) not in shape and (yy in (0,bh-1) or xx in (0,bw-1)):
                        outside.add((yy,xx)); q.append((yy,xx))
            while q:
                yy,xx=q.pop()
                for ny,nx in ((yy-1,xx),(yy+1,xx),(yy,xx-1),(yy,xx+1)):
                    if 0 <= ny < bh and 0 <= nx < bw and (ny,nx) not in shape and (ny,nx) not in outside:
                        outside.add((ny,nx)); q.append((ny,nx))
            has_hole = any((yy,xx) not in shape and (yy,xx) not in outside for yy in range(bh) for xx in range(bw))
            objs.append({'cells':cells,'minr':minr,'minc':minc,'bh':bh,'top':has_hole})
    out = [[0]*w for _ in range(h)]
    # Pack hole-containing objects against the top, preserving their left-to-right
    # positions and source order where their columns overlap.
    placed = []
    def fits(obj, y):
        for yy,xx in obj['cells']:
            ny = y + yy - obj['minr']
            nx = xx
            if out[ny][nx] != 0:
                return False
        return True
    for obj in sorted((o for o in objs if o['top']), key=lambda o:(o['minr'],o['minc'])):
        for y in range(h-obj['bh']+1):
            if fits(obj,y):
                for yy,xx in obj['cells']:
                    out[y + yy-obj['minr']][xx] = grid[yy][xx]
                break
    for obj in sorted((o for o in objs if not o['top']), key=lambda o:(-o['minr'],-o['minc'])):
        for y in range(h-obj['bh'],-1,-1):
            if fits(obj,y):
                for yy,xx in obj['cells']:
                    out[y + yy-obj['minr']][xx] = grid[yy][xx]
                break
    return out
